/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: managed
 *   Constants: sample, redTone
 * Tests
 *   - samples the 96 px variant once per image id and serves later reads from the cache
 *   - settles failed, unreadable, and transparent artwork to a cached neutral tone
 *   - useArtworkTone reports a pending sample as null, then the tone, and reuses it at once
 *   - useArtworkTone ignores a sample that finishes after the artwork changed
 *   - useMainPaneTone tints the shell main pane while mounted and switches without a gap
 *   - setMainPaneTone is a no-op outside the listener shell
 * @end-catalog */

import { act, cleanup, render, renderHook, waitFor } from '@testing-library/react';

import { sampleArtworkTone } from './artworkTone';
import {
  loadArtworkTone,
  neutralArtworkTone,
  peekArtworkTone,
  setMainPaneTone,
  useArtworkTone,
  useMainPaneTone
} from './useArtworkTone';

vi.mock('./artworkTone', () => ({ sampleArtworkTone: vi.fn() }));

const sample = vi.mocked(sampleArtworkTone);
const redTone = { hero: '#7a1f2b', pane: '#4f141c' };
// The module cache lives for the whole file, so every test uses its own image ids.
const managed = (suffix: string) => `/content/images/${suffix.padStart(24, '0')}`;

afterEach(() => {
  cleanup();
  document.body.innerHTML = '';
});

test('samples the 96 px variant once per image id and serves later reads from the cache', async () => {
  sample.mockResolvedValue(redTone);
  const source = managed('a1');

  expect(peekArtworkTone(source)).toBeUndefined();
  const [first, second] = await Promise.all([loadArtworkTone(source), loadArtworkTone(` ${source} `)]);

  expect(first).toEqual(redTone);
  expect(second).toEqual(redTone);
  expect(sample).toHaveBeenCalledTimes(1);
  expect(sample).toHaveBeenCalledWith(`${source}/v1/96.webp`);
  expect(peekArtworkTone(source)).toEqual(redTone);
  await expect(loadArtworkTone(source)).resolves.toEqual(redTone);
  expect(sample).toHaveBeenCalledTimes(1);
});

test.each([
  ['missing', ''],
  ['external', 'https://images.example.com/cover.webp'],
  ['unversioned query', '/content/images/0123456789abcdef01234567?revision=2'],
  ['non-managed path', '/__e2e__/artwork/first-light.jpg']
])('uses the neutral tone without sampling %s artwork', async (_name, source) => {
  expect(peekArtworkTone(source)).toBe(neutralArtworkTone);
  await expect(loadArtworkTone(source)).resolves.toBe(neutralArtworkTone);
  expect(sample).not.toHaveBeenCalled();
});

test('settles failed, unreadable, and transparent artwork to a cached neutral tone', async () => {
  sample.mockRejectedValueOnce(new DOMException('decode failed', 'EncodingError'));
  sample.mockRejectedValueOnce(new DOMException('tainted', 'SecurityError'));
  sample.mockResolvedValueOnce(null);

  for (const id of ['b1', 'b2', 'b3']) {
    await expect(loadArtworkTone(managed(id))).resolves.toBe(neutralArtworkTone);
    expect(peekArtworkTone(managed(id))).toBe(neutralArtworkTone);
  }
  await loadArtworkTone(managed('b1'));
  expect(sample).toHaveBeenCalledTimes(3);
});

test('useArtworkTone reports a pending sample as null, then the tone, and reuses it at once', async () => {
  let finish!: (tone: typeof redTone) => void;
  sample.mockReturnValue(new Promise((resolve) => { finish = resolve; }));
  const source = managed('c1');

  const { result, rerender } = renderHook(({ url }) => useArtworkTone(url), { initialProps: { url: source } });
  expect(result.current).toBeNull();
  await act(async () => finish(redTone));
  expect(result.current).toEqual(redTone);

  rerender({ url: '' });
  expect(result.current).toBe(neutralArtworkTone);
  const cachedView = renderHook(() => useArtworkTone(source));
  expect(cachedView.result.current).toEqual(redTone);
  expect(sample).toHaveBeenCalledTimes(1);
});

test('useArtworkTone ignores a sample that finishes after the artwork changed', async () => {
  let finishFirst!: (tone: typeof redTone) => void;
  sample.mockReturnValueOnce(new Promise((resolve) => { finishFirst = resolve; }));
  sample.mockResolvedValueOnce({ hero: '#1f4f7a', pane: '#16384f' });

  const { result, rerender } = renderHook(({ url }) => useArtworkTone(url), { initialProps: { url: managed('d1') } });
  rerender({ url: managed('d2') });
  await waitFor(() => expect(result.current).toEqual({ hero: '#1f4f7a', pane: '#16384f' }));
  await act(async () => finishFirst(redTone));
  expect(result.current).toEqual({ hero: '#1f4f7a', pane: '#16384f' });
});

test('useMainPaneTone tints the shell main pane while mounted and switches without a gap', () => {
  render(<main id="main-content" />);
  const main = document.getElementById('main-content')!;
  const { rerender, unmount } = renderHook(({ color }) => useMainPaneTone(color), {
    initialProps: { color: redTone.pane as string | null }
  });
  expect(main.style.getPropertyValue('--tone-color')).toBe(redTone.pane);

  rerender({ color: '#16384f' });
  expect(main.style.getPropertyValue('--tone-color')).toBe('#16384f');
  rerender({ color: null });
  expect(main.style.getPropertyValue('--tone-color')).toBe('');

  rerender({ color: '#16384f' });
  unmount();
  expect(main.style.getPropertyValue('--tone-color')).toBe('');
});

test('setMainPaneTone is a no-op outside the listener shell', () => {
  expect(() => setMainPaneTone('#16384f')).not.toThrow();
  expect(() => setMainPaneTone(null)).not.toThrow();
});
